<?php

namespace Database\Seeders;

use App\Models\{Category,LogisticsHub,LogisticsInsight,LogisticsInvoice,LogisticsSetting,NotificationModel,Order,OrderItem,Payment,Product,ProofOfDelivery,RiderProfile,SellerOrder,SellerProfile,Shipment,ShipmentAssignment,ShipmentEvent,Store,User,Vehicle};
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\{DB,Storage};
use RuntimeException;

class LogisticsDemoSeeder extends Seeder
{
    public function run(): void
    {
        if (! app()->environment(['local','testing'])) {
            throw new RuntimeException('LogisticsDemoSeeder is restricted to local/testing environments.');
        }

        DB::transaction(function () {
            $logistics=$this->user('SHOPPICK Logistics','logistics@shoppick.test','logistics');
            $hubs=[
                'cavinti'=>LogisticsHub::updateOrCreate(['code'=>'DEMO-CAVINTI'],['name'=>'Cavinti Hub','address'=>'Cavinti, Laguna','capacity'=>100,'status'=>'active','notes'=>'DEMO ONLY']),
                'santa_cruz'=>LogisticsHub::updateOrCreate(['code'=>'DEMO-SANTA-CRUZ'],['name'=>'Santa Cruz Hub','address'=>'Santa Cruz, Laguna','capacity'=>80,'status'=>'active','notes'=>'DEMO ONLY']),
                'maintenance'=>LogisticsHub::updateOrCreate(['code'=>'DEMO-MAINTENANCE'],['name'=>'Maintenance Hub','address'=>'Laguna Operations Area','capacity'=>40,'status'=>'maintenance','notes'=>'DEMO ONLY — temporarily under maintenance']),
            ];
            $riders=[
                'juan'=>$this->rider('Rider Juan','rider.juan@shoppick.test',$hubs['santa_cruz'],'available',4.80),
                'maria'=>$this->rider('Rider Maria','rider.maria@shoppick.test',$hubs['cavinti'],'on_delivery',4.70),
                'carlo'=>$this->rider('Rider Carlo','rider.carlo@shoppick.test',$hubs['cavinti'],'assigned',4.50),
            ];
            $vehicles=[
                'moto1'=>Vehicle::updateOrCreate(['code'=>'MOTO-001'],['plate_number'=>'DEMO-M001','type'=>'motorcycle','make'=>'SHOPPICK Demo','model'=>'Courier Moto','year'=>2025,'hub_id'=>$hubs['santa_cruz']->id,'status'=>'available','maintenance_due_at'=>now()->addMonths(3),'notes'=>'DEMO ONLY — maintenance good']),
                'van1'=>Vehicle::updateOrCreate(['code'=>'VAN-001'],['plate_number'=>'DEMO-V001','type'=>'van','make'=>'SHOPPICK Demo','model'=>'Delivery Van','year'=>2025,'hub_id'=>$hubs['cavinti']->id,'status'=>'in_use','maintenance_due_at'=>now()->addMonth(),'notes'=>'DEMO ONLY — assigned to LOAD-1002']),
                'moto2'=>Vehicle::updateOrCreate(['code'=>'MOTO-002'],['plate_number'=>'DEMO-M002','type'=>'motorcycle','make'=>'SHOPPICK Demo','model'=>'Courier Moto','year'=>2024,'hub_id'=>$hubs['maintenance']->id,'status'=>'maintenance','maintenance_due_at'=>now()->subDay(),'notes'=>'DEMO ONLY — maintenance due']),
            ];

            $flows=[
                ['n'=>1,'order'=>'ORD-1001','load'=>'LOAD-1001','shop'=>'Panda Picks','buyer'=>'Demo Buyer One','qty'=>2,'method'=>'card','payment'=>'paid','fee'=>60,'rider'=>$riders['juan'],'vehicle'=>$vehicles['moto1'],'hub'=>null,'status'=>'delivered','eta'=>now()->subMinutes(15),'delivered'=>now()->subMinutes(30),'note'=>'Direct delivery completed; POD approved.'],
                ['n'=>2,'order'=>'ORD-1002','load'=>'LOAD-1002','shop'=>'Tech Corner','buyer'=>'Demo Buyer Two','qty'=>3,'method'=>'cod','payment'=>'cod','fee'=>80,'rider'=>$riders['maria'],'vehicle'=>$vehicles['van1'],'hub'=>$hubs['cavinti'],'status'=>'in_transit','eta'=>now()->addHours(2),'delivered'=>null,'note'=>'Active Hub delivery. Waiting for real Rider browser location.'],
                ['n'=>3,'order'=>'ORD-1003','load'=>'LOAD-1003','shop'=>'Home Finds','buyer'=>'Demo Buyer Three','qty'=>1,'method'=>'card','payment'=>'paid','fee'=>50,'rider'=>$riders['carlo'],'vehicle'=>$vehicles['moto2'],'hub'=>null,'status'=>'exception','eta'=>now()->subHour(),'delivered'=>null,'note'=>'Recipient unavailable'],
            ];
            $created=[];
            foreach($flows as $flow)$created[$flow['n']]=$this->flow($flow,$logistics);
            $created[1]->update(['ready_at'=>now()->subHours(7),'assigned_at'=>now()->subHours(6),'picked_up_at'=>now()->subHours(5)]);
            $created[2]->update(['ready_at'=>now()->subHours(6),'assigned_at'=>now()->subHours(5),'picked_up_at'=>now()->subHours(4)]);
            $created[3]->update(['ready_at'=>now()->subHours(5),'assigned_at'=>now()->subHours(4),'picked_up_at'=>now()->subHours(3)]);

            $this->events($created[1],$riders['juan'],['ready_for_pickup','assigned','picked_up','in_transit','out_for_delivery','delivered']);
            $this->events($created[2],$riders['maria'],['ready_for_pickup','assigned','picked_up','at_hub','in_transit']);
            $this->events($created[3],$riders['carlo'],['ready_for_pickup','assigned','picked_up','in_transit','delivery_attempted','exception']);
            DB::table('hub_movements')->updateOrInsert(['shipment_id'=>$created[2]->id,'type'=>'inbound'],['from_hub_id'=>null,'to_hub_id'=>$hubs['cavinti']->id,'recorded_by'=>$logistics->id,'note'=>'DEMO ONLY — arrived at Cavinti Hub','moved_at'=>now()->subHours(3),'created_at'=>now()->subHours(3),'updated_at'=>now()]);

            Storage::disk('local')->put('pod/demo-load-1001.svg','<svg xmlns="http://www.w3.org/2000/svg" width="900" height="560"><rect width="100%" height="100%" fill="#e6fffb"/><text x="50%" y="45%" text-anchor="middle" font-family="Arial" font-size="52" fill="#0f766e">SHOPPICK DEMO POD</text><text x="50%" y="57%" text-anchor="middle" font-family="Arial" font-size="34" fill="#334155">LOAD-1001 — Delivered</text></svg>');
            ProofOfDelivery::updateOrCreate(['shipment_id'=>$created[1]->id],['submitted_by'=>$riders['juan']->id,'recipient_name'=>'Demo Buyer One','photo_path'=>'pod/demo-load-1001.svg','notes'=>'DEMO ONLY evidence','status'=>'approved','reviewed_by'=>$logistics->id,'review_notes'=>'Demo evidence approved','submitted_at'=>now()->subMinutes(25),'reviewed_at'=>now()->subMinutes(20)]);
            ProofOfDelivery::updateOrCreate(['shipment_id'=>$created[2]->id],['submitted_by'=>$riders['maria']->id,'recipient_name'=>'Pending delivery','photo_path'=>null,'notes'=>'DEMO ONLY — pending upload after delivery','status'=>'pending','reviewed_by'=>null,'review_notes'=>null,'submitted_at'=>now(),'reviewed_at'=>null]);
            ProofOfDelivery::updateOrCreate(['shipment_id'=>$created[3]->id],['submitted_by'=>$riders['carlo']->id,'recipient_name'=>'Not available','photo_path'=>null,'notes'=>'DEMO ONLY — delivery attempt evidence','status'=>'rejected','reviewed_by'=>$logistics->id,'review_notes'=>'Photo evidence unclear','submitted_at'=>now()->subHour(),'reviewed_at'=>now()->subMinutes(45)]);

            LogisticsInvoice::updateOrCreate(['invoice_number'=>'INV-LG-1001'],['shipment_id'=>$created[1]->id,'delivery_fee'=>60,'adjustments'=>0,'total'=>60,'status'=>'paid','due_at'=>now()->subDays(7),'paid_at'=>now()->subDays(8),'notes'=>'DEMO ONLY — settled delivery fee']);
            LogisticsInvoice::updateOrCreate(['invoice_number'=>'INV-LG-1002'],['shipment_id'=>$created[2]->id,'delivery_fee'=>80,'adjustments'=>0,'total'=>80,'status'=>'issued','due_at'=>now()->addDays(7),'paid_at'=>null,'notes'=>'DEMO ONLY — COD settlement pending']);
            $agedInvoice=LogisticsInvoice::updateOrCreate(['invoice_number'=>'INV-LG-1003'],['shipment_id'=>$created[3]->id,'delivery_fee'=>50,'adjustments'=>20,'total'=>70,'status'=>'overdue','due_at'=>now()->subDays(95),'paid_at'=>null,'notes'=>'DEMO ONLY — approved redelivery adjustment under review']);$agedInvoice->timestamps=false;$agedInvoice->created_at=now()->subDays(100);$agedInvoice->save();

            $this->historicalReports($logistics,$riders,$vehicles,$hubs);
            $this->insights($created,$riders,$vehicles);
            $this->notification($logistics,'demo-load-ready-1002','New order/load ready for pickup.','LOAD-1002 is ready for Logistics handling.',route('logistics.shipments.show',$created[2]));
            $this->notification($riders['maria'],'demo-assignment-1002','New delivery assignment: LOAD-1002.','VAN-001 has been assigned.',route('rider.shipments.show',$created[2]));
            $this->notification($logistics,'demo-exception-1003','Delivery exception reported for LOAD-1003.','Recipient unavailable.',route('logistics.shipments.show',$created[3]));
            foreach(['notify_pickup_delay'=>true,'notify_pod'=>true,'notify_vehicle_maintenance'=>false,'enable_live_tracking'=>true,'buyer_tracking_visibility'=>true,'tracking_interval_seconds'=>20] as $key=>$value)LogisticsSetting::updateOrCreate(['key'=>$key],['value'=>['value'=>$value],'updated_by'=>$logistics->id]);
        });
    }

    private function user(string $name,string $email,string $role):User {$user=User::withTrashed()->where('email',$email)->first();if($user?->trashed())$user->restore();$user=User::updateOrCreate(['email'=>$email],['name'=>$name,'phone'=>'0917'.str_pad((string)(crc32($email)%10000000),7,'0',STR_PAD_LEFT),'password'=>'password','is_active'=>true,'email_verified_at'=>now()]);$user->assignRole($role);return $user;}
    private function rider(string $name,string $email,LogisticsHub $hub,string $availability,float $rating):User {$user=$this->user($name,$email,'rider');RiderProfile::updateOrCreate(['user_id'=>$user->id],['hub_id'=>$hub->id,'account_status'=>'active','availability'=>$availability,'rating'=>$rating,'notes'=>'DEMO ONLY']);return $user;}
    private function flow(array $f,User $actor):Shipment {
        $buyer=$this->user($f['buyer'],'demo.buyer'.$f['n'].'@shoppick.test','buyer');$seller=$this->user($f['shop'].' Seller','demo.seller'.$f['n'].'@shoppick.test','seller');$profile=SellerProfile::updateOrCreate(['user_id'=>$seller->id],['phone'=>$seller->phone,'address'=>'Laguna Demo Address','business_information'=>'DEMO ONLY','status'=>'approved','approved_at'=>now()->subMonth()]);$store=Store::updateOrCreate(['slug'=>'demo-shop-'.$f['n']],['user_id'=>$seller->id,'seller_profile_id'=>$profile->id,'name'=>$f['shop'],'description'=>'DEMO ONLY Logistics Shop','location'=>'Seller Shop, Laguna','status'=>'active']);$category=Category::firstOrCreate(['slug'=>'logistics-demo'],['name'=>'Logistics Demo','is_active'=>true]);$product=Product::updateOrCreate(['slug'=>'logistics-demo-item-'.$f['n']],['store_id'=>$store->id,'category_id'=>$category->id,'name'=>'Demo Logistics Item '.$f['n'],'description'=>'DEMO ONLY','sku'=>'DEMO-LG-'.$f['n'],'price'=>100,'stock'=>100,'is_active'=>true,'publication_status'=>'active','moderation_status'=>'approved']);$subtotal=$f['qty']*100;$order=Order::updateOrCreate(['order_number'=>$f['order']],['user_id'=>$buyer->id,'status'=>$f['status']==='delivered'?'delivered':'shipped','payment_method'=>$f['method'],'payment_status'=>$f['payment'],'subtotal'=>$subtotal,'shipping_fee'=>$f['fee'],'total'=>$subtotal+$f['fee'],'buyer_name'=>$buyer->name,'buyer_phone'=>$buyer->phone,'shipping_address'=>['address_line'=>'Demo Buyer Address '.$f['n'],'barangay'=>'Demo Barangay','city'=>$f['n']===2?'Santa Cruz':'Cavinti','province'=>'Laguna'],'paid_at'=>$f['payment']==='paid'?now()->subDays(2):null]);$sellerOrder=SellerOrder::updateOrCreate(['seller_order_number'=>$f['order'].'-S1'],['order_id'=>$order->id,'store_id'=>$store->id,'status'=>$f['status']==='delivered'?'delivered':'shipped','subtotal'=>$subtotal,'shipping_fee'=>$f['fee'],'seller_total'=>$subtotal]);OrderItem::updateOrCreate(['order_id'=>$order->id,'product_id'=>$product->id],['seller_order_id'=>$sellerOrder->id,'product_name'=>$product->name,'sku'=>$product->sku,'price'=>100,'quantity'=>$f['qty'],'total'=>$subtotal]);Payment::updateOrCreate(['order_id'=>$order->id],['method'=>$f['method'],'status'=>$f['payment']==='paid'?'paid':'pending','reference'=>'DEMO-PAY-'.$f['n'],'amount'=>$subtotal+$f['fee'],'paid_at'=>$f['payment']==='paid'?now()->subDays(2):null]);$shipment=Shipment::updateOrCreate(['shipment_number'=>$f['load']],['seller_order_id'=>$sellerOrder->id,'order_id'=>$order->id,'store_id'=>$store->id,'rider_id'=>$f['rider']->id,'vehicle_id'=>$f['vehicle']->id,'current_hub_id'=>$f['hub']?->id,'status'=>$f['status'],'priority'=>$f['status']==='exception'?'high':'normal','pickup_address'=>['address'=>'Seller Shop, Laguna'],'delivery_address'=>$order->shipping_address,'ready_at'=>now()->subDays(2),'assigned_at'=>now()->subDays(2)->addHour(),'picked_up_at'=>now()->subDays(2)->addHours(2),'estimated_delivery_at'=>$f['eta'],'delivered_at'=>$f['delivered'],'internal_notes'=>'DEMO ONLY — '.$f['note']]);ShipmentAssignment::updateOrCreate(['shipment_id'=>$shipment->id],['rider_id'=>$f['rider']->id,'vehicle_id'=>$f['vehicle']->id,'assigned_by'=>$actor->id,'assigned_at'=>now()->subDays(2)->addHour(),'ended_at'=>$f['status']==='delivered'?now()->subMinutes(30):null,'reason'=>'DEMO ONLY connected flow']);return $shipment;
    }
    private function events(Shipment $shipment,User $rider,array $statuses):void {foreach($statuses as $i=>$status)ShipmentEvent::updateOrCreate(['shipment_id'=>$shipment->id,'status'=>$status],['actor_id'=>$i? $rider->id:null,'location'=>$status==='at_hub'?'Cavinti Hub':null,'note'=>$status==='exception'?'Recipient unavailable':'DEMO ONLY — '.ucwords(str_replace('_',' ',$status)),'created_at'=>now()->subHours(count($statuses)-$i),'updated_at'=>now()->subHours(count($statuses)-$i)]);}
    private function historicalReports(User $actor,array $riders,array $vehicles,array $hubs):void {foreach([['n'=>11,'r'=>$riders['juan'],'v'=>$vehicles['moto1'],'days'=>20,'late'=>-15,'city'=>'Santa Cruz','fee'=>45],['n'=>12,'r'=>$riders['maria'],'v'=>$vehicles['van1'],'days'=>12,'late'=>-10,'city'=>'Pagsanjan','fee'=>75],['n'=>13,'r'=>$riders['carlo'],'v'=>$vehicles['moto1'],'days'=>5,'late'=>40,'city'=>'Cavinti','fee'=>55]] as $x){$f=['n'=>$x['n'],'order'=>'ORD-HIST-'.$x['n'],'load'=>'LOAD-HIST-'.$x['n'],'shop'=>'Demo Historical Shop '.$x['n'],'buyer'=>'Demo Historical Buyer '.$x['n'],'qty'=>1,'method'=>'card','payment'=>'paid','fee'=>$x['fee'],'rider'=>$x['r'],'vehicle'=>$x['v'],'hub'=>$hubs['santa_cruz'],'status'=>'delivered','eta'=>now()->subDays($x['days'])->setTime(16,0),'delivered'=>now()->subDays($x['days'])->setTime(16,0)->addMinutes($x['late']),'note'=>'Historical report demo'];$s=$this->flow($f,$actor);$s->timestamps=false;$s->created_at=now()->subDays($x['days']);$s->updated_at=$f['delivered'];$s->save();$invoice=LogisticsInvoice::updateOrCreate(['invoice_number'=>'INV-LG-HIST-'.$x['n']],['shipment_id'=>$s->id,'delivery_fee'=>$x['fee'],'adjustments'=>0,'total'=>$x['fee'],'status'=>'paid','due_at'=>now()->subDays($x['days']-7),'paid_at'=>now()->subDays($x['days']),'notes'=>'DEMO ONLY historical revenue']);$invoice->timestamps=false;$invoice->created_at=now()->subDays($x['days']);$invoice->save();}}
    private function insights(array $loads,array $riders,array $vehicles):void {$items=[['rider_vehicle','info','Rider Juan + MOTO-001','Available Rider and available Motorcycle are compatible.'],['rider_vehicle','info','Rider Maria + VAN-001','Suitable Vehicle at the same Hub with an active compatible assignment.'],['rider_vehicle','warning','Rider Carlo requires another Vehicle','MOTO-002 is under maintenance and must not be recommended.'],['delay_risk','critical','LOAD-1003 — High Risk','A delivery exception exists: recipient unavailable.'],['delay_risk','warning','LOAD-1002 ETA monitoring','Active Hub delivery should be monitored against its promised timestamp.'],['delay_risk','info','Hub dwell review','Review loads that remain at a Hub beyond the configured threshold.'],['cost_leak','warning','Repeated redelivery cost','LOAD-1003 has a legitimate redelivery adjustment for human review.'],['cost_leak','warning','Vehicle maintenance cost','MOTO-002 is under maintenance; review operating impact.'],['cost_leak','info','Duplicate adjustment candidate','Review repeated positive adjustments before settlement.'],['billing_anomaly','warning','Possible duplicate invoice','Human review required; no automatic financial correction.'],['billing_anomaly','warning','Missing delivery fee check','Compare ready Loads with Logistics invoices.'],['billing_anomaly','critical','Overdue settlement','INV-LG-1003 is overdue and requires review.']];foreach($items as $i=>$v)LogisticsInsight::updateOrCreate(['title'=>$v[2]],['type'=>$v[0],'severity'=>$v[1],'explanation'=>'DEMO ONLY — '.$v[3],'status'=>'generated','target_type'=>Shipment::class,'target_id'=>$loads[min(3,($i%3)+1)]->id]);}
    private function notification(User $user,string $marker,string $title,string $body,string $link):void {NotificationModel::updateOrCreate(['user_id'=>$user->id,'type'=>$marker],['title'=>$title,'body'=>'DEMO ONLY — '.$body,'icon'=>'package','link'=>$link,'data'=>['demo'=>true]]);}
}
